#!/usr/bin/env python3
"""Stamp brand/config.yaml into TypeScript, i18n, and index.html.

Edit frontend/web/brand/config.yaml, then run this script.
"""
from __future__ import annotations

import argparse
import json
import re
import sys
from pathlib import Path

SCRIPT_DIR = Path(__file__).resolve().parent
sys.path.insert(0, str(SCRIPT_DIR / "lib"))

from brand_config import BrandConfig, load_brand_config  # noqa: E402

WEB = SCRIPT_DIR.parent


def write(path: Path, text: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    if not text.endswith("\n"):
        text += "\n"
    path.write_text(text, encoding="utf-8")
    print(f"  wrote {path.relative_to(WEB)}")


def ts_escape(value: str) -> str:
    return value.replace("\\", "\\\\").replace("'", "\\'")


def rewrite_translation_value(value: str, new_name: str, brand: BrandConfig) -> str:
    names = [new_name, *brand.legacy_display]
    names = sorted(set(names), key=len, reverse=True)
    for old in names:
        if old == new_name:
            continue
        if re.search(r"[A-Za-z]", old):
            value = re.sub(rf"(?<![A-Za-z]){re.escape(old)}(?![A-Za-z])", new_name, value)
            value = value.replace(f"\\n{old}", f"\\n{new_name}")
        else:
            value = value.replace(old, new_name)
    return value


def rewrite_json_values(obj, new_name: str, brand: BrandConfig):
    if isinstance(obj, dict):
        return {key: rewrite_json_values(val, new_name, brand) for key, val in obj.items()}
    if isinstance(obj, list):
        return [rewrite_json_values(item, new_name, brand) for item in obj]
    if isinstance(obj, str):
        return rewrite_translation_value(obj, new_name, brand)
    return obj


def write_brand_generated(brand: BrandConfig) -> None:
    write(
        WEB / "src" / "config" / "brand.generated.ts",
        f"""// Generated by scripts/apply-brand.py from brand/config.yaml.
// Do not edit by hand.

export const brandValues = {{
  productName: '{ts_escape(brand.name_en)}',
  productNameZh: '{ts_escape(brand.name_zh)}',
  siteUrl: '{ts_escape(brand.site_url)}',
  appPath: '{ts_escape(brand.app_path)}',
  termsUrl: '{ts_escape(brand.terms_url)}',
  privacyUrl: '{ts_escape(brand.privacy_url)}',
  downloadUrl: '{ts_escape(brand.download_url)}',
  githubUrl: '{ts_escape(brand.github_url)}',
  githubIssuesUrl: '{ts_escape(brand.github_issues_url)}',
  twitterHandle: '{ts_escape(brand.twitter_handle)}',
  discordUrl: '{ts_escape(brand.discord_url)}',
  docsUrl: '{ts_escape(brand.docs_url)}',
  whatsNewUrl: '{ts_escape(brand.whats_new_url)}',
  templatesUrl: '{ts_escape(brand.templates_url)}',
  forumUrl: '{ts_escape(brand.forum_url)}',
  redditUrl: '{ts_escape(brand.reddit_url)}',
  desktopScheme: '{ts_escape(brand.desktop_scheme)}',
  legacyDesktopScheme: '{ts_escape(brand.legacy_desktop_scheme)}',
  description: '{ts_escape(brand.description)}',
}} as const;
""",
    )


def stamp_translations(brand: BrandConfig) -> None:
    translations = WEB / "src" / "@types" / "translations"
    for path in sorted(translations.glob("*.json")):
        name = brand.display_for_locale(path.stem)
        original = path.read_text(encoding="utf-8")
        data = json.loads(original)
        data = rewrite_json_values(data, name, brand)
        if isinstance(data, dict):
            data["appName"] = name
        dumped = json.dumps(data, ensure_ascii=False, indent=2) + "\n"
        if dumped != original:
            path.write_text(dumped, encoding="utf-8")
            print(f"  patched translations/{path.name} → {name}")


def replace_named_attr(text: str, name_attr: str, name_value: str, content: str, path: Path) -> str:
    pattern = rf'({name_attr}=["\']{re.escape(name_value)}["\']\s+content=["\'])[^"\']*'
    updated, count = re.subn(pattern, rf"\g<1>{content}", text, count=1, flags=re.S)
    if count != 1:
        raise ValueError(f"{path}: expected 1 match for {name_attr}={name_value}, got {count}")
    return updated


def stamp_index_html(brand: BrandConfig) -> None:
    path = WEB / "index.html"
    original = path.read_text(encoding="utf-8")
    text = original
    en = brand.name_en
    desc = brand.description
    site = brand.site_url.rstrip("/")
    twitter = f"@{brand.twitter_handle}" if brand.twitter_handle else ""

    text, count = re.subn(
        r'(rel=["\']icon["\'][\s\S]*?href=["\'])[^"\']*',
        r"\g<1>/favicon.svg",
        text,
        count=1,
    )
    if count != 1:
        raise ValueError(f"{path}: expected 1 icon href")
    text, count = re.subn(
        r'(rel=["\']canonical["\']\s+href=["\'])[^"\']*',
        rf"\g<1>{site}",
        text,
        count=1,
        flags=re.S,
    )
    if count != 1:
        raise ValueError(f"{path}: expected 1 canonical href")
    text, count = re.subn(r"(<title>)[^<]*(</title>)", rf"\g<1>{en}\2", text, count=1)
    if count != 1:
        raise ValueError(f"{path}: expected 1 title")
    text = replace_named_attr(text, "name", "description", desc, path)
    text = replace_named_attr(text, "property", "og:title", en, path)
    text = replace_named_attr(text, "property", "og:site_name", en, path)
    text = replace_named_attr(text, "property", "og:description", desc, path)
    text = replace_named_attr(text, "property", "og:url", site, path)
    text = replace_named_attr(text, "name", "twitter:title", en, path)
    text = replace_named_attr(text, "name", "twitter:description", desc, path)
    text = replace_named_attr(text, "name", "twitter:site", twitter, path)
    text = replace_named_attr(text, "name", "twitter:creator", twitter, path)
    if text != original:
        path.write_text(text, encoding="utf-8")
        print("  patched index.html")


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--config", type=Path, default=None)
    args = parser.parse_args()
    brand = load_brand_config(args.config)
    print(f"Applying {brand.name_en} / {brand.name_zh}")
    write_brand_generated(brand)
    stamp_index_html(brand)
    stamp_translations(brand)
    print("Done.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
